head.script:
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 4. 브라우저에서 선택하는 화살표가 아닌, ALL 부분을 클릭한다.
    //4. Click the ALL button, not the arrow that you select in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_label').focus()");
    // verify step 4. ALL 의 Edit Mode 로 진입한다.
    //4. Enter the edit mode of ALL.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_input').css('display')", "block");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_input').val()", "ALL");
    //Test step 5. ALL 을 지운다.
    //5. Delete ALL.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#wq_uuid_3_input').val('')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 5. ALL 이 지워져서 빈 란이 된다.
    //5. ALL is erased and becomes an empty column.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_input').val() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 6. 비어있는(다른곳) 부분을 클릭한다.
    //6. Click on the empty (elsewhere) part.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#wq_uuid_3_input').blur()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 6. Focus Out 되면서 ALL 이 다시 표시된다.
    //6. Focus out and ALL is displayed again.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_input').val()", "ALL");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 08-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
